// ============================================
// VALIDATION INPUT - Multi-Provider PDF OCR
// ============================================

const input = $input.first().json;
const body = input.body || input;

// Support RFC-014: data in context.* with fallback to root level
const ctx = body.context || {};

const errors = [];

// --- Valid providers ---
const validProviders = ['mistral', 'google', 'mathpix'];
const provider = body.provider || ctx.provider || 'mistral';

if (!validProviders.includes(provider)) {
  errors.push(`Invalid provider: '${provider}'. Valid options: ${validProviders.join(', ')}`);
}

// --- Extract PDF URL and/or base64 data ---
const fileUrl = ctx.file_url || ctx.pdf_url || body.file_url || body.pdf_url;
let fileData = ctx.file_data || body.file_data || null;

// Clean base64 data (remove data:image/...;base64, prefix if present)
if (fileData && fileData.includes(',')) {
  fileData = fileData.split(',')[1];
}

// Need either file_url or file_data
if (!fileUrl && !fileData) {
  errors.push('file_url ou file_data requis');
}

// --- Check required API keys based on provider ---
const mistralKey = body.mistral_api_key || ctx.mistral_api_key || body.plugin_context?.api_keys?.mistral;
const googleKey = body.google_api_key || ctx.google_api_key || body.plugin_context?.api_keys?.google;
const mathpixAppId = body.mathpix_app_id || ctx.mathpix_app_id || body.plugin_context?.api_keys?.mathpix_app_id;
const mathpixAppKey = body.mathpix_app_key || ctx.mathpix_app_key || body.plugin_context?.api_keys?.mathpix_app_key;

if (provider === 'mistral' && !mistralKey) {
  errors.push('mistral_api_key requis pour provider mistral');
}
if (provider === 'google' && !googleKey) {
  errors.push('google_api_key requis pour provider google');
}
if (provider === 'mathpix' && (!mathpixAppId || !mathpixAppKey)) {
  errors.push('mathpix_app_id et mathpix_app_key requis pour provider mathpix');
}

// --- Extract context fields ---
const projectId = ctx.project_id || body.project_id || body.plugin_context?.plugin_id;
const guildId = ctx.guild_id || body.guild_id;
const userId = ctx.user_id || body.user_id;

// --- RFC-040: Extract async callback fields ---
const callbackUrl = body.callback_url || ctx.callback_url;
// Generate UUID without crypto (n8n doesn't support Node.js crypto module)
const generateUUID = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
  const r = Math.random() * 16 | 0;
  return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
});
const jobId = body.job_id || ctx.job_id || generateUUID();

// --- Options ---
const includeImages = body.include_images || ctx.include_images || false;

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    callbackUrl: callbackUrl,
    jobId: jobId
  };
}

// --- Determine Google mode ---
// googleMode: 'gcs' (gs:// URL), 'base64' (file_data provided), 'http' (need to download)
let googleMode = null;
if (provider === 'google') {
  if (fileUrl && fileUrl.startsWith('gs://')) {
    googleMode = 'gcs';
  } else if (fileData) {
    googleMode = 'base64';
  } else if (fileUrl) {
    googleMode = 'http'; // Will download and convert to base64
  }
}

return {
  valid: true,
  fileUrl: fileUrl,
  fileData: fileData,
  provider: provider,
  googleMode: googleMode,
  mistralApiKey: mistralKey,
  googleApiKey: googleKey,
  mathpixAppId: mathpixAppId,
  mathpixAppKey: mathpixAppKey,
  includeImages: includeImages,
  callbackUrl: callbackUrl,
  jobId: jobId,
  startTime: Date.now(),
  context: {
    project_id: projectId,
    guild_id: guildId,
    user_id: userId
  }
};

// ============================================
// GOOGLE VISION OCR (Sync) - Multi-mode
// Handles: GCS URLs, base64 data, HTTP URLs
// ============================================

const data = $input.first().json;
const googleMode = data.googleMode;
const apiKey = data.googleApiKey;

try {
  let base64Data = data.fileData;

  // --- Mode HTTP: Download image and convert to base64 ---
  if (googleMode === 'http') {
    const response = await this.helpers.httpRequest({
      method: 'GET',
      url: data.fileUrl,
      encoding: 'arraybuffer',
      returnFullResponse: true
    });
    base64Data = Buffer.from(response.body).toString('base64');
  }

  // --- Mode GCS: Use files:asyncBatchAnnotate ---
  if (googleMode === 'gcs') {
    const gcsResponse = await this.helpers.httpRequest({
      method: 'POST',
      url: `https://vision.googleapis.com/v1/files:asyncBatchAnnotate?key=${apiKey}`,
      headers: { 'Content-Type': 'application/json' },
      body: {
        requests: [{
          inputConfig: {
            gcsSource: { uri: data.fileUrl },
            mimeType: 'application/pdf'
          },
          features: [{ type: 'DOCUMENT_TEXT_DETECTION' }],
          outputConfig: {
            gcsDestination: { uri: 'gs://temp-ocr-output/' },
            batchSize: 100
          }
        }]
      },
      json: true,
      returnFullResponse: true
    });
    return { body: gcsResponse.body, statusCode: gcsResponse.statusCode };
  }

  // --- Mode base64 or http (after download): Use images:annotate ---
  const visionResponse = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://vision.googleapis.com/v1/images:annotate?key=${apiKey}`,
    headers: { 'Content-Type': 'application/json' },
    body: {
      requests: [{
        image: { content: base64Data },
        features: [{ type: 'DOCUMENT_TEXT_DETECTION' }]
      }]
    },
    json: true,
    returnFullResponse: true
  });

  return { body: visionResponse.body, statusCode: visionResponse.statusCode };

} catch (error) {
  return {
    error: { message: error.message },
    statusCode: 500
  };
}

