// ============================================
// NORMALIZE MISTRAL OCR RESPONSE
// ============================================

const input = $input.first().json;
const prevData = $('Validate Input').first().json;

const data = input.body || input;
const statusCode = input.statusCode || 200;

// --- Check for API error ---
if (statusCode >= 400 || input.error) {
  const errorMessage = data.message || data.error?.message || input.error?.message || 'Mistral API error';
  return {
    success: false,
    _trace: {
      reasoning: [
        { step: 'detect_input_type', result: 'pdf', pages: 0 },
        { step: 'select_provider', result: 'mistral', reason: 'priority_list' },
        { step: 'process_mode', result: 'sync', reason: 'error' }
      ],
      provider: 'mistral',
      mode: 'sync',
      latency_ms: Date.now() - (prevData.startTime || Date.now())
    },
    error: {
      code: 'OCR_API_ERROR',
      message: errorMessage,
      provider: 'mistral',
      http_status: statusCode >= 400 ? statusCode : 500
    },
    context: prevData.context
  };
}

// --- Extract text from pages ---
const pages = data.pages || [];
const text = pages.map(p => p.markdown).join('\n\n');

const pageDetails = pages.map((p, idx) => ({
  page: idx + 1,
  markdown: p.markdown,
  has_images: p.images?.length > 0 || false
}));

return {
  success: true,
  _trace: {
    reasoning: [
      { step: 'detect_input_type', result: 'pdf', pages: pageDetails.length },
      { step: 'select_provider', result: 'mistral', reason: 'priority_list' },
      { step: 'process_mode', result: 'sync', reason: pageDetails.length > 1 ? 'multi_page' : 'single_page' }
    ],
    provider: 'mistral',
    mode: 'sync',
    latency_ms: Date.now() - (prevData.startTime || Date.now())
  },
  data: {
    text: text,
    pages: pageDetails,
    page_count: pages.length
  },
  meta: {
    provider: 'mistral',
    model: data.model || 'mistral-ocr-latest',
    usage: {
      pages_processed: data.usage_info?.pages_processed || pages.length,
      doc_size_bytes: data.usage_info?.doc_size_bytes || 0
    }
  },
  context: prevData.context
};

